// Stripe webhook signature verification + payload extraction
// Supports multiple webhook secrets for dual-account setup.
const crypto = require('crypto');

const WEBHOOK_SECRETS = [
  process.env.STRIPE_WHSEC_TANDEM,     // Tandem Stripe (tandemcoach.co checkout)
  process.env.STRIPE_WHSEC_HEARTBEAT   // Heartbeat Stripe (community platform)
].filter(Boolean);
const TOLERANCE = 300; // 5 minutes

const raw = $input.first().json;
const sigHeader = (raw.headers || {})['stripe-signature'] || '';
const rawBody = raw.rawBody || '';

// ── Signature verification ──
const parts = {};
sigHeader.split(',').forEach(part => {
  const [key, value] = part.split('=', 2);
  if (key === 't') parts.t = value;
  if (key === 'v1') {
    if (!parts.v1) parts.v1 = [];
    parts.v1.push(value);
  }
});

const timestamp = parseInt(parts.t, 10);
const signatures = parts.v1 || [];

if (!timestamp || signatures.length === 0 || !rawBody) {
  return []; // reject: missing signature components
}

const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - timestamp) > TOLERANCE) {
  return []; // reject: timestamp outside tolerance
}

const signedPayload = `${timestamp}.${rawBody}`;
let verified = false;
for (const secret of WEBHOOK_SECRETS) {
  const expected = crypto
    .createHmac('sha256', secret)
    .update(signedPayload)
    .digest('hex');
  if (signatures.includes(expected)) {
    verified = true;
    break;
  }
}

if (!verified) {
  return []; // reject: no matching signature
}

// ── Parse and validate event ──
let body;
try {
  body = JSON.parse(rawBody);
} catch {
  return [];
}

const eventType = typeof body.type === 'string' ? body.type : '';
const eventId = typeof body.id === 'string' ? body.id : '';

const ALLOWED_EVENTS = [
  'payment_intent.succeeded',
  'checkout.session.completed'
];

if (!ALLOWED_EVENTS.includes(eventType)) {
  return [];
}

const dataObj = body.data && typeof body.data === 'object' ? body.data : {};
const innerObj = dataObj.object && typeof dataObj.object === 'object' ? dataObj.object : {};
const stripeId = typeof innerObj.id === 'string' ? innerObj.id : '';

if (!stripeId.match(/^(pi|cs)_[A-Za-z0-9_]{10,80}$/)) {
  return [];
}

if (!eventId.match(/^evt_[A-Za-z0-9_]{10,80}$/)) {
  return [];
}

return [{
  json: {
    stripe_id: stripeId,
    event_type: eventType
  }
}];
